def product_card(kind,title,desc,url,price=None,label='Đang nghiên cứu',badge='AI AGENT',cat='agent',sku=None,order=0):
    marks={'muse':'M','grok':'G','gpt':'✳','pack':'✦'}
    shown=(f'<div class="price">{price}</div>' if price else '<div class="price price-empty">Liên hệ tư vấn</div>')
    price_sort={'69.000đ':69000,'699.000đ':699000}.get(price,'')
    return f'''<article class="product-card" data-name="{escape(title.lower())}" data-category="{cat}" data-price="{price_sort}" data-order="{order}"><a href="{url}" class="product-art {kind}" aria-label="Xem {escape(title)}"><span class="art-top">{badge}</span><span class="orbit"></span><span class="blob"><span class="art-mark">{marks[kind]}</span></span><span class="art-symbol">✳</span></a><div class="product-body"><div class="product-meta"><span class="tag tag-{ 'orange' if price else 'blue' }">{label}</span><span class="tag">Tìm hiểu gói</span></div><h3><a href="{url}">{title}</a></h3><p class="product-desc">{desc}</p><div class="product-footer"><div><div class="price-label">{'Giá BotHub dự kiến từ' if price else 'Tình trạng'}</div>{shown}</div><a class="btn btn-sm btn-line" href="{url}" aria-label="Xem chi tiết {escape(title)}">Xem gói ↗</a></div></div></article>'''

